package service

import (
	"context"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"time"
	"github.com/ynw0/airgap-mirror/internal/domain"
	"github.com/ynw0/airgap-mirror/internal/pack"
	"github.com/ynw0/airgap-mirror/internal/ports"
)

type ImportService struct{Store ports.ServerStore;Installer ports.ArtifactInstaller;Manifest ManifestReader;Publisher PublisherService;Now func()time.Time}
func(i ImportService)now()time.Time{if i.Now!=nil{return i.Now()};return time.Now()}
func(i ImportService)CommitPack(ctx context.Context,sessionID,packID string)error{sess,err:=i.Store.GetImportSession(ctx,sessionID);if err!=nil{return err};if sess.Status!="MANIFEST_READY"&&sess.Status!="IMPORTING"{return fmt.Errorf("manifest is not ready: status=%s: %w",sess.Status,domain.ErrConflict)};ip,err:=i.Store.GetImportPack(ctx,sessionID,packID);if err!=nil{return err};if ip.Status==domain.PackImported{return nil};if ip.Status!=domain.PackUploaded{return fmt.Errorf("pack status %s is not uploaded: %w",ip.Status,domain.ErrConflict)};if err=verifyUploadedPack(ip);err!=nil{return err};pmeta,err:=i.Store.GetPack(ctx,packID);if err!=nil{return err};source,err:=i.Store.GetSource(ctx,sess.SourceID);if err!=nil{return err};r,err:=pack.Open(ip.StagingPath);if err!=nil{return err};defer r.Close();h:=r.Header();if h.PackID!=packID||h.EpochID!=sess.EpochID||h.BatchID!=sess.BatchID{return fmt.Errorf("pack header identity mismatch: %w",domain.ErrConflict)};batch,err:=i.Store.GetBatch(ctx,sess.BatchID);if err!=nil{return err};if batch.Status==domain.BatchTransferring{if err=i.Store.TransitionBatch(ctx,batch.ID,domain.BatchImporting,"");err!=nil{return err}};sess.Status="IMPORTING";sess.UpdatedAt=i.now();if err=i.Store.UpdateImportSession(ctx,sess);err!=nil{return err};var count int64;err=i.Manifest.WalkPack(ctx,sess.ManifestPath,packID,func(m domain.ManifestEntry)error{rec,body,e:=r.Next(ctx);if e!=nil{return fmt.Errorf("read pack record %d: %w",count,e)};if m.PackID!=packID||m.EntryID!=rec.EntryID||m.PackOffset!=rec.Offset||m.RecordLength!=rec.RecordLength||m.Artifact.LogicalPath!=rec.LogicalPath||m.Artifact.Size!=rec.ContentLength||m.Artifact.SHA256!=rec.SHA256||m.Artifact.SourceID!=sess.SourceID||m.Artifact.EpochID!=sess.EpochID{return fmt.Errorf("manifest/pack record mismatch entry=%s: %w",m.EntryID,domain.ErrConflict)};if m.Artifact.Operation==domain.ArtifactDelete{return fmt.Errorf("DELETE import is not implemented until GC phase: %w",domain.ErrInvalid)};var staged string;if m.Artifact.Metadata{logical:=filepath.ToSlash(filepath.Join(".airgap-staging",sess.EpochID,m.Artifact.PublishUnitID,filepath.FromSlash(m.Artifact.LogicalPath)));staged,e=safeTarget(source.RootPath,logical);if e!=nil{return e};_,e=writeVerified(source.RootPath,staged,rec.ContentLength,rec.SHA256,body,false);if e!=nil{return e}}else{if i.Installer==nil{return fmt.Errorf("artifact installer required")};if _,e=i.Installer.Install(ctx,source,rec,body);e!=nil{return e}};c:=domain.CatalogEntry{SourceID:m.Artifact.SourceID,LogicalPath:m.Artifact.LogicalPath,Size:m.Artifact.Size,SHA256:m.Artifact.SHA256,PackageKey:m.Artifact.PackageKey,Version:m.Artifact.Version,Attributes:m.Artifact.Attributes,UpdatedAt:i.now()};if _,e=i.Store.CommitImportedEntry(ctx,m,c,staged);e!=nil{return e};count++;return nil});if err!=nil{return err};if count!=pmeta.EntryCount{return fmt.Errorf("manifest entries=%d pack declaration=%d: %w",count,pmeta.EntryCount,domain.ErrConflict)};if _,_,err=r.Next(ctx);err!=io.EOF{return fmt.Errorf("pack contains undeclared trailing record: %w",domain.ErrConflict)};if err=i.Store.MarkImportPackCommitted(ctx,sessionID,packID);err!=nil{return err};if err=os.Remove(ip.StagingPath);err!=nil&&!os.IsNotExist(err){return err};if err=i.Publisher.PublishReady(ctx,sess.EpochID);err!=nil{return err};id,_:=domain.NewID();_ = i.Store.WriteAudit(ctx,domain.AuditEvent{ID:id,Kind:"pack_imported",SourceID:sess.SourceID,EpochID:sess.EpochID,BatchID:sess.BatchID,Message:"pack imported: "+packID,CreatedAt:i.now()});return nil}
func(i ImportService)CompleteBatch(ctx context.Context,sessionID string)error{sess,err:=i.Store.GetImportSession(ctx,sessionID);if err!=nil{return err};packs,err:=i.Store.ListPacks(ctx,sess.BatchID);if err!=nil{return err};for _,p:=range packs{if p.Status!=domain.PackImported{return fmt.Errorf("pack %s is %s: %w",p.ID,p.Status,domain.ErrConflict)}};b,err:=i.Store.GetBatch(ctx,sess.BatchID);if err!=nil{return err};if b.Status==domain.BatchTransferring{if err=i.Store.TransitionBatch(ctx,b.ID,domain.BatchImporting,"");err!=nil{return err};b.Status=domain.BatchImporting};if b.Status==domain.BatchImporting{if err=i.Store.TransitionBatch(ctx,b.ID,domain.BatchImported,"");err!=nil{return err}};sess.Status="BATCH_IMPORTED";sess.UpdatedAt=i.now();if err=i.Store.UpdateImportSession(ctx,sess);err!=nil{return err};if err=i.Publisher.PublishReady(ctx,sess.EpochID);err!=nil{return err};ep,err:=i.Store.GetEpoch(ctx,sess.EpochID);if err!=nil{return err};imported,err:=i.Store.CountImportedBatches(ctx,ep.ID);if err!=nil{return err};published,err:=i.Store.CountPublishedUnits(ctx,ep.ID);if err!=nil{return err};if imported==ep.TotalBatches{if published!=ep.PublishUnitCount{return fmt.Errorf("all batches imported but publish units=%d/%d: %w",published,ep.PublishUnitCount,domain.ErrConflict)};if ep.Status==domain.EpochTransferring{if err=i.Store.TransitionEpoch(ctx,ep.ID,domain.EpochPublishable,"");err!=nil{return err};ep.Status=domain.EpochPublishable};if ep.Status==domain.EpochPublishable{if err=i.Store.TransitionEpoch(ctx,ep.ID,domain.EpochPublished,"");err!=nil{return err}};stats,err:=i.Publisher.Catalog.Stats(ctx,ep.SourceID);if err!=nil{return err};if err=i.Store.CompleteEpoch(ctx,ep.ID,stats,i.now());err!=nil{return err}};return nil}
